CREATE TABLE public.companion_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, friend_id uuid, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now(), CHECK (friend_id IS NULL OR friend_id <> owner_id));
GRANT SELECT, INSERT, DELETE ON public.companion_rooms TO authenticated;
GRANT ALL ON public.companion_rooms TO service_role;
ALTER TABLE public.companion_rooms ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_companion_room(p_room uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.companion_rooms r WHERE r.id = p_room AND (r.owner_id = auth.uid() OR r.friend_id = auth.uid()) AND (r.friend_id IS NULL OR public.are_connected(r.owner_id, r.friend_id))); $$;
REVOKE ALL ON FUNCTION public.can_access_companion_room(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_companion_room(uuid) TO authenticated, service_role;
CREATE POLICY companion_room_read ON public.companion_rooms FOR SELECT TO authenticated USING (public.can_access_companion_room(id));
CREATE POLICY companion_room_create ON public.companion_rooms FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND (friend_id IS NULL OR public.are_connected(owner_id, friend_id)));
CREATE POLICY companion_room_delete ON public.companion_rooms FOR DELETE TO authenticated USING (owner_id = auth.uid());
CREATE TABLE public.companion_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.companion_rooms(id) ON DELETE CASCADE, sender_id uuid, role text NOT NULL CHECK (role IN ('user','assistant')), content text NOT NULL CHECK (char_length(content) BETWEEN 1 AND 4500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.companion_messages TO authenticated;
GRANT ALL ON public.companion_messages TO service_role;
ALTER TABLE public.companion_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY companion_message_read ON public.companion_messages FOR SELECT TO authenticated USING (public.can_access_companion_room(room_id));
CREATE POLICY companion_message_create ON public.companion_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND role = 'user' AND public.can_access_companion_room(room_id));
CREATE INDEX companion_message_order ON public.companion_messages(room_id, created_at, id);
CREATE TABLE public.companion_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300), due_at timestamptz, completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.companion_tasks TO authenticated;
GRANT ALL ON public.companion_tasks TO service_role;
ALTER TABLE public.companion_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY companion_task_owner ON public.companion_tasks FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());